  width: 350px;
  height: 350px;
  background: linear-gradient(45deg, #ff1493, #ff6347);
  top: 70%;
  left: 70%;
  clip-path: polygon(10% 10%, 90% 10%, 100% 90%, 0% 90%);
  transform: translate(-50%, -50%) rotate(-30deg);
